"""Build dependency-free static pages. Configure the real domain before publishing."""
import json
import re
from pathlib import Path
from html import escape
from urllib.parse import quote, urlparse
from xml.sax.saxutils import escape as xml_escape

ROOT = Path(__file__).resolve().parents[1]
config = json.loads((ROOT / 'site-config.json').read_text(encoding='utf-8'))
domain = config['domain'].rstrip('/')
if domain:
    parsed = urlparse(domain)
    if parsed.scheme != 'https' or not parsed.hostname or parsed.query or parsed.fragment or parsed.path not in ('', '/') or parsed.username or parsed.password:
        raise ValueError('domain must be the real HTTPS origin, e.g. https://your-academy.in')
phone = config['phone']
if not re.fullmatch(r'\+91\d{10}', phone):
    raise ValueError('phone must contain +91 followed by ten digits')
email = escape(config['email'])
address = escape(config['streetAddress']) + ', Hyderabad, Telangana ' + escape(config['postalCode'])
whatsapp = 'https://wa.me/' + phone.lstrip('+')
directions = 'https://www.google.com/maps/search/?api=1&query=' + quote(config['streetAddress'] + ', Hyderabad ' + config['postalCode'])
NAV = [('courses-page.html','Programs'),('abacus-page.html','Abacus'),('about-page.html','About us'),('online-abacus-classes.html','Online classes')]
PAGES = {}

def image(src, alt, width, height, eager=False, cls=''):
    return f'<img src="assets/images/{src}.webp" alt="{escape(alt)}" width="{width}" height="{height}" class="{cls}" {"fetchpriority=high" if eager else "loading=lazy"} decoding="async">'

def brand():
    return '<a class="brand" href="index.html" aria-label="The Numbers Academy home"><span class="brand-mark" aria-hidden="true"><img src="assets/images/academy-logo.webp" alt="" width="52" height="52"></span><span>The Numbers Academy<small>LITTLE MINDS. BIG POSSIBILITIES.</small></span></a>'

def render(path, title, description, content, schema=None):
    PAGES[path] = title
    canonical = domain + '/' + ('' if path == 'index.html' else quote(path))
    seo = f'<link rel="canonical" href="{canonical}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{domain}/assets/images/learning-hero.webp"><meta name="twitter:image" content="{domain}/assets/images/learning-hero.webp">' if domain else ''
    nav = ''.join(f'<a href="{href}" {"aria-current=page" if href == path else ""}>{label}</a>' for href,label in NAV)
    structured = '<script type="application/ld+json">' + json.dumps(schema, ensure_ascii=False).replace('<','\\u003c') + '</script>' if schema else ''
    footer = f'''<footer class="site-footer"><div class="wrap"><div class="footer-grid"><div>{brand()}<p>Making numbers feel like possibilities.<br>Abacus, Vedic Maths &amp; Rubik’s Cube learning.</p></div><div><h3>Explore programs</h3><a href="abacus-page.html">Abacus</a><a href="vedic-math-page.html">Vedic Maths</a><a href="rubiks-cube-page.html">Rubik’s Cube</a></div><div><h3>Learn your way</h3><a href="abacus-classes-hyderabad.html">Hyderabad classes</a><a href="online-abacus-classes.html">Online abacus classes</a><a href="about-page.html">About the academy</a><a href="contact-page.html">Contact us</a></div><div><h3>Come say hello</h3><p>{address}</p><a href="tel:{phone}">{phone[:3]} {phone[3:]}</a><a href="mailto:{email}">{email}</a></div></div><div class="footer-bottom"><span>© The Numbers Academy. Empowering young minds.</span><span>Vidya Nagar, Hyderabad · Online learning</span></div></div></footer>'''
    html = f'''<!doctype html>
<html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | The Numbers Academy</title><meta name="description" content="{escape(description)}"><meta name="theme-color" content="#19584a"><meta property="og:type" content="website"><meta property="og:site_name" content="The Numbers Academy"><meta property="og:locale" content="en_IN"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(description)}"><meta name="twitter:card" content="summary_large_image">{seo}<link rel="icon" href="assets/favicon.png" type="image/png"><link rel="stylesheet" href="assets/site.css"><script src="assets/site.js" defer></script>{structured}</head>
<body><a class="skip" href="#main">Skip to content</a><div class="announcement">A little practice. A world of confidence. <a href="abacus-classes-hyderabad.html">Hyderabad</a> &amp; <a href="online-abacus-classes.html">online classes ↗</a></div><header class="site-header"><nav class="wrap nav" aria-label="Main navigation">{brand()}<button class="menu-toggle" aria-expanded="false" aria-controls="main-navigation" aria-label="Toggle navigation">☰</button><div class="nav-links" id="main-navigation">{nav}<a class="button" href="contact-page.html" {"aria-current=page" if path == "contact-page.html" else ""}>Enquire now <span aria-hidden="true">↗</span></a></div></nav></header><main id="main">{content}</main>{footer}</body></html>'''
    (ROOT / path).write_text(html, encoding='utf-8')

def cta():
    return '<section class="wrap bottom-space"><div class="cta"><div><span class="eyebrow" style="color:#ffcca5">LET’S GET STARTED</span><h2>Big possibilities begin with a small hello.</h2><p>Tell us about your child. We’ll help you explore the right program.</p></div><a class="button light" href="contact-page.html">Talk to the academy ↗</a></div></section>'

def cards():
    programs = [('abacus','Abacus training','Hands-on learning','Build a foundation in numbers, then work towards mental arithmetic.','abacus-page.html','Soroban abacus used for arithmetic practice',780,585),('vedic','Vedic Maths','Think beyond the textbook','Explore practical calculation strategies for multiplication, division and more.','vedic-math-page.html','Vedic Mathematics learning illustration',910,550),('cube','Rubik’s Cube','A colourful challenge','Discover patterns, follow a solving method and practise step by step.','rubiks-cube-page.html','Colourful Rubik’s Cube puzzle',675,380)]
    return '<div class="grid">' + ''.join(f'<article class="card"><div class="card-image">{image(src,alt,w,h)}</div><div class="card-body"><span class="badge">{badge}</span><h3>{name}</h3><p>{text}</p><a href="{href}">Explore the program <span aria-hidden="true">↗</span></a></div></article>' for src,name,badge,text,href,alt,w,h in programs) + '</div>'

def head(title, intro, eyebrow='LEARN. PRACTISE. GROW.'):
    return f'<div class="wrap"><header class="page-head"><div class="breadcrumbs"><a href="index.html">Home</a> / {escape(title)}</div><span class="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{intro}</p></header></div>'

def modes():
    return f'''<section class="section wrap"><span class="eyebrow">YOUR ROUTINE. YOUR WAY.</span><h2>One learning journey.<br>Two ways to join.</h2><div class="modes"><article class="mode"><span class="number" aria-hidden="true">⌂</span><span class="badge">IN PERSON · HYDERABAD</span><h3>A place to learn, together.</h3><p>Join offline abacus classes at our Vidya Nagar centre in Hyderabad. Explore hands-on learning with face-to-face guidance.</p><p>{address}</p><a class="text-link" href="abacus-classes-hyderabad.html">Explore Hyderabad classes ↗</a></article><article class="mode"><span class="number" aria-hidden="true">↗</span><span class="badge">ONLINE · FROM HOME</span><h3>Bring the classroom home.</h3><p>Choose online abacus learning when travelling to the centre does not fit your routine. Ask us about available online batches and learning materials.</p><p>A learning space, an abacus and an internet connection.</p><a class="text-link" href="online-abacus-classes.html">Explore online abacus ↗</a></article></div></section>'''

FAQ = [('Do you offer offline abacus classes in Hyderabad?','Yes. The Numbers Academy offers in-person abacus classes at 204 C Block, Vaidehi Nivas, Golden Palms, Achyuta Reddy Marg, Vidya Nagar, Hyderabad, Telangana 500044. Contact us before visiting to confirm batch availability.'),('Can my child learn abacus online?','Online abacus classes are available. Contact the academy to discuss the current batches, how lessons are conducted and the materials your child will need.'),('What will my child learn in abacus classes?','Students begin with number representation and addition and subtraction on an abacus, then progress to multi-digit calculations and mental arithmetic practice. The starting level depends on the learner’s current skills.'),('What are the fees and class timings?','Please contact the teacher for current fees, batch timings and availability. These may vary by program, level and whether you choose online or in-person learning.'),('How do I choose the right program for my child?','Share your child’s age, familiarity with arithmetic and learning goals with us. We can explain the differences between abacus, Vedic Maths and Rubik’s Cube training and discuss a suitable starting point.')]
