def alias(path, target):
    canonical = f'<link rel="canonical" href="{domain}/{target}">' if domain else ''
    (ROOT / path).write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>The Numbers Academy</title><meta name="robots" content="noindex,follow">{canonical}<meta http-equiv="refresh" content="0;url={target}"></head><body><p>This page has moved. <a href="{target}">Continue to The Numbers Academy</a>.</p></body></html>',encoding='utf-8')
alias('educational-website.html','index.html')
alias('rubiks-cube-page (1).html','rubiks-cube-page.html')
alias('comments-app/frontend/comments-page.html','../../comments-page.html')
(ROOT / 'robots.txt').write_text('User-agent: *\nAllow: /\nDisallow: /api/\n' + (f'Sitemap: {domain}/sitemap.xml\n' if domain else ''),encoding='utf-8')
if domain:
    urls = ''.join('<url><loc>'+xml_escape(domain+'/' + ('' if path=='index.html' else path))+'</loc></url>' for path in PAGES)
    (ROOT / 'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+urls+'</urlset>',encoding='utf-8')
elif (ROOT / 'sitemap.xml').exists():
    (ROOT / 'sitemap.xml').unlink()
print(f'Built {len(PAGES)} pages. ' + ('Canonical URLs and sitemap configured.' if domain else 'Set the live domain in site-config.json and rebuild to enable canonical URLs and sitemap.'))
